//! Static gamepad mapping database (SDL_GameControllerDB line format).
//! Pure data leaf: `resolve` finds a pad by USB IDs, the `RawMapping`
//! accessors translate raw indices, and the deadzone math lives here so
//! backends never implement it per OS.

use nerust_input_traits::{GamepadAxis, StandardButton};

/// One pad mapping: USB identity plus logical-to-physical index tables.
/// Generated by `build.rs` from `db.txt` (current target platform only).
#[derive(Debug, Clone, Copy)]
pub struct RawMapping {
    /// USB vendor id from GUID bytes 4..6.
    pub vendor_id: u16,
    /// USB product id from GUID bytes 8..10.
    pub product_id: u16,
    /// SDL display name (informational only, never a lookup key).
    pub name: &'static str,
    /// Logical button to physical button index (`bN`).
    pub buttons: &'static [(StandardButton, u8)],
    /// Logical axis to physical axis index (`aN`).
    pub axes: &'static [(GamepadAxis, u8)],
    /// Logical button to physical hat (`hN.M`: hat index, direction mask).
    pub hats: &'static [(StandardButton, u8, u8)],
}

include!(concat!(env!("OUT_DIR"), "/mappings.rs"));

impl RawMapping {
    /// Physical button index driving one logical button, if mapped.
    pub fn button_index(self, button: StandardButton) -> Option<u8> {
        self.buttons
            .iter()
            .find(|(logical, _)| *logical == button)
            .map(|(_, physical)| *physical)
    }

    /// Physical axis index driving one logical axis, if mapped.
    pub fn axis_index(self, axis: GamepadAxis) -> Option<u8> {
        self.axes
            .iter()
            .find(|(logical, _)| *logical == axis)
            .map(|(_, physical)| *physical)
    }

    /// Physical hat (index, direction mask) driving one logical button.
    pub fn hat(self, button: StandardButton) -> Option<(u8, u8)> {
        self.hats
            .iter()
            .find(|(logical, _, _)| *logical == button)
            .map(|(_, index, mask)| (*index, *mask))
    }

    /// Logical button for one physical button index. Inverts the SDL
    /// table so HID readers (SDL-indexed) resolve without re-parsing.
    pub fn button_for_index(self, physical: u8) -> Option<StandardButton> {
        self.buttons
            .iter()
            .find(|(_, index)| *index == physical)
            .map(|(logical, _)| *logical)
    }

    /// Logical axis for one physical axis index.
    pub fn axis_for_index(self, physical: u8) -> Option<GamepadAxis> {
        self.axes
            .iter()
            .find(|(_, index)| *index == physical)
            .map(|(logical, _)| *logical)
    }

    /// Every logical button held by one hat state. Diagonals match two
    /// entries, so callers collect instead of taking the first.
    pub fn hat_buttons(self, hat: u8, value: u8, out: &mut Vec<StandardButton>) {
        out.extend(
            self.hats
                .iter()
                .filter(|(_, index, mask)| *index == hat && value & mask != 0)
                .map(|(logical, _, _)| *logical),
        );
    }
}

/// Find the mapping for one USB device. `None` means unknown pad
/// (Phase 3 fallback: pass through instead of refusing the device).
pub fn resolve(vendor_id: u16, product_id: u16) -> Option<&'static RawMapping> {
    MAPPINGS
        .iter()
        .find(|mapping| mapping.vendor_id == vendor_id && mapping.product_id == product_id)
}

/// Whether one hat direction is held (`hat` is the raw hat bitmask).
pub const fn hat_pressed(hat: u8, mask: u8) -> bool {
    hat & mask != 0
}

/// Deadzone with rescale: inside the zone is `0.0`, the rim stays `1.0`.
/// `deadzone >= 1.0` parks everything at neutral instead of dividing by zero.
pub fn apply_deadzone(value: f32, deadzone: f32) -> f32 {
    if deadzone >= 1.0 || value.abs() < deadzone {
        return 0.0;
    }
    (value - deadzone.copysign(value)) / (1.0 - deadzone)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolve_finds_phase1_pads_and_rejects_unknown() {
        assert!(resolve(0x9999, 0x9999).is_none());
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn linux_table_holds_the_three_representatives() {
        // (vid, pid, probe button, physical index, probe axis).
        for (vid, pid, button, index, axis) in [
            (
                0x045e,
                0x028e,
                StandardButton::South,
                0,
                GamepadAxis::LeftStickX,
            ),
            (
                0x054c,
                0x05c4,
                StandardButton::South,
                0,
                GamepadAxis::LeftStickX,
            ),
            (
                0x057e,
                0x2009,
                StandardButton::South,
                1,
                GamepadAxis::LeftStickX,
            ),
        ] {
            let mapping = resolve(vid, pid).expect("representative must resolve");
            assert_eq!(mapping.button_index(button), Some(index));
            assert_eq!(mapping.axis_index(axis), Some(0));
            assert!(!mapping.name.is_empty());
        }
        let pro = resolve(0x057e, 0x2009).expect("switch pro");
        assert_eq!(pro.hat(StandardButton::DpadUp), Some((0, 1)));
        assert!(pro.hat(StandardButton::South).is_none());
        assert!(MAPPINGS.iter().all(|m| !m.buttons.is_empty()));
    }

    #[test]
    fn reverse_lookups_invert_the_forward_tables() {
        // Xbox 360 ships on every platform table, so this runs un-gated.
        let pad = resolve(0x045e, 0x028e).expect("xbox 360");
        assert_eq!(pad.button_for_index(0), Some(StandardButton::South));
        assert_eq!(pad.button_for_index(99), None);
        assert_eq!(pad.axis_for_index(0), Some(GamepadAxis::LeftStickX));
        assert_eq!(pad.axis_for_index(9), None);
        let mut held = Vec::new();
        pad.hat_buttons(0, 1, &mut held);
        assert_eq!(held, vec![StandardButton::DpadUp]);
        held.clear();
        pad.hat_buttons(0, 3, &mut held);
        assert!(held.contains(&StandardButton::DpadUp));
        assert!(held.contains(&StandardButton::DpadRight));
        held.clear();
        pad.hat_buttons(1, 1, &mut held);
        assert!(held.is_empty());
    }

    #[test]
    fn deadzone_parks_and_rescales() {
        assert_eq!(apply_deadzone(0.05, 0.1), 0.0);
        assert_eq!(apply_deadzone(-0.05, 0.1), 0.0);
        assert_eq!(apply_deadzone(1.0, 0.2), 1.0);
        assert_eq!(apply_deadzone(-1.0, 0.2), -1.0);
        assert!((apply_deadzone(0.6, 0.2) - 0.5).abs() < 1e-6);
        assert_eq!(apply_deadzone(0.9, 1.0), 0.0);
        assert_eq!(apply_deadzone(0.9, 2.0), 0.0);
        assert!(!hat_pressed(0b0000, 0b0001));
        assert!(hat_pressed(0b0001, 0b0001));
        assert!(!hat_pressed(0b0100, 0b0001));
    }
}
